TOPBAR='''<header class="topbar"><a class="brand" href="/"><span class="brand-mark">JT</span><span>JT 灵感工作台</span></a><nav class="topnav"><a class="topnav-link" href="/">创作台</a><a class="topnav-link __SKETCH_ACTIVE__" href="/original-sketch">原始铅绘</a><a class="topnav-link __GRAPHIC_ACTIVE__" href="/original-graphic">原始古风</a><a class="topnav-link" href="/video">视频</a></nav><div class="topbar-tools"><button class="topbar-action" id="cloudFavOpen">♥ 收藏</button><button class="topbar-action" id="cloudHistOpen">⌛ 历史</button></div></header>'''

UI_BASE=r'''
<section class="cloud-panel" id="cloudPanel"><div class="cloud-head"><h2>生成设置</h2></div><div class="prompt-mode-box"><select id="cloudPromptMode"><option value="options">原始随机选项</option><option value="manual">手动提示词</option></select><button class="import-prompt" id="importGeneratedPrompt" type="button">导入并编辑</button><div class="manual-panel" id="cloudManualPanel"><textarea id="manualPositive" placeholder="正向提示词"></textarea><textarea id="manualNegative" placeholder="负向提示词"></textarea></div></div><div class="cloud-grid"><label>宽<input id="cloudW" type="number" value="768" min="256" max="2048" step="16"></label><label>高<input id="cloudH" type="number" value="1024" min="256" max="2048" step="16"></label><label>批量<input id="cloudBatch" type="number" value="1" min="1" max="4"><span id="cloudBatchNote" style="display:none"></span></label><label>高清<select id="cloudHd"><option value="0">关闭</option><option value="1">ClearReality 2×</option><option value="2">UltraSharp 2×</option></select></label><label>种子模式<select id="cloudSeedMode"><option value="random">每次随机</option><option value="fixed">固定</option></select></label><label>种子值<input id="cloudSeed" type="number" min="1" max="9007199254740991" step="1"></label>__SEQUENCE__</div></section>
'''
FOOTER=r'''</div><div class="creation-footer"><div class="generation-actions"><button class="liquid-button cloud" id="cloudGenerateCloud"><span class="liquid-wave"></span><span class="liquid-label">☁ 云端生图</span></button><button class="liquid-button local" id="cloudGenerateLocal"><span class="liquid-wave"></span><span class="liquid-label">本地生成</span></button></div></div></aside>'''
PREVIEW=r'''<section class="preview-pane"><div class="preview-header"><h2>创作预览</h2><div class="result-tabs"><button class="result-tab active" data-result-tab="cloud">云端结果</button><button class="result-tab" data-result-tab="local">本地结果</button></div></div><div class="preview-stage"><div class="preview-empty" id="previewEmpty"><div class="empty-icon">✦</div><strong>你的创作将呈现在这里</strong><span>使用原始随机选项，或导入后手动调整</span></div><section class="result-panel active" data-result-panel="cloud"><div id="cloudStatusCloud"></div><div class="cloud-result" id="cloudResultCloud"></div></section><section class="result-panel" data-result-panel="local"><div id="cloudStatusLocal"></div><div class="cloud-result" id="cloudResultLocal"></div></section></div></section></main>'''
OVERLAYS=r'''<div class="library-overlay" id="cloudHistOverlay"><div class="library-panel"><div class="library-header"><h2>历史记录</h2><button class="cloud-close">×</button></div><div class="library-scroll"><div id="cloudHistList"></div></div></div></div><div class="library-overlay" id="cloudFavOverlay"><div class="library-panel"><div class="library-header"><h2>我的收藏</h2><button class="cloud-close">×</button></div><div class="library-scroll"><div id="cloudFavList"></div></div></div></div>'''

JS=r'''<script>
const CLOUD_STYLE_ID='__STYLE__',CLOUD_TRIGGER='__TRIGGER__',CLOUD_PAGE_ID='__PAGE__',CLOUD_HAS_SEQUENCE=__HAS_SEQUENCE__;let cloudRunning={cloud:false,local:false};
const cloudApi=async(path,opt={})=>{const r=await fetch(path,opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('HTTP '+r.status));return d};
function cloudNewSeed(){return Math.floor(Math.random()*9007199254740990)+1}function cloudStripStyleTokens(t){return String(t||'').replace(/(?<![A-Za-z0-9_])jt_style\d+_v\d+(?![A-Za-z0-9_])/gi,'').replace(/(?:\s*,\s*){2,}/g,', ').replace(/^\s*,|,\s*$/g,'').trim()}function cloudSequenceMode(){if(!CLOUD_HAS_SEQUENCE)return'off';return cloudSequence.value==='3'?'sketch3':(cloudSequence.value==='4'?'sketch4':'off')}function cloudUpdateBatch(){const staged=CLOUD_HAS_SEQUENCE&&cloudSequence.value!=='off';cloudBatch.disabled=staged;if(staged)cloudBatch.value=1;cloudBatchNote.textContent=''}
function importGeneratedPromptToManual(){manualPositive.value=cloudStripStyleTokens(buildPositive());manualNegative.value=NEGATIVE;cloudPromptMode.value='manual';cloudManualPanel.classList.add('open');manualPositive.focus()}function updateCloudPromptMode(){cloudManualPanel.classList.toggle('open',cloudPromptMode.value==='manual')}function setLiquidLoading(b,on){b.classList.toggle('is-loading',on);b.setAttribute('aria-busy',on?'true':'false')}function setResultTab(b){document.querySelectorAll('[data-result-tab]').forEach(x=>x.classList.toggle('active',x.dataset.resultTab===b));document.querySelectorAll('[data-result-panel]').forEach(x=>x.classList.toggle('active',x.dataset.resultPanel===b))}
function cloudSnapshot(backend){return{source_page:CLOUD_PAGE_ID,style:CLOUD_STYLE_ID,mode:currentMode,state:JSON.parse(JSON.stringify(state)),locked:JSON.parse(JSON.stringify(locked)),trigger_input:document.getElementById('triggerInput')?.value||'',prefix_input:document.getElementById('prefixInput')?.value||'',width:+cloudW.value,height:+cloudH.value,batch:+cloudBatch.value,hd:+cloudHd.value,sequence_mode:cloudSequenceMode(),prompt_mode:cloudPromptMode.value,manual_positive:manualPositive.value,manual_negative:manualNegative.value,seed:+cloudSeed.value,seed_mode:cloudSeedMode.value,generation_backend:backend}}
function cloudApplySnapshot(s){if(!s||s.source_page!==CLOUD_PAGE_ID||!s.state)return;state=JSON.parse(JSON.stringify(s.state));locked=JSON.parse(JSON.stringify(s.locked||{}));currentMode=s.mode||'original';if(document.getElementById('triggerInput'))triggerInput.value=s.trigger_input||'';if(document.getElementById('prefixInput'))prefixInput.value=s.prefix_input||'';cloudW.value=s.width||768;cloudH.value=s.height||1024;cloudBatch.value=s.batch||1;cloudHd.value=s.hd||0;cloudSeed.value=s.seed||cloudNewSeed();cloudSeedMode.value=s.seed_mode||'fixed';cloudPromptMode.value=s.prompt_mode||'options';manualPositive.value=s.manual_positive||'';manualNegative.value=s.manual_negative||'';if(CLOUD_HAS_SEQUENCE)cloudSequence.value=s.sequence_mode==='sketch3'?'3':(s.sequence_mode==='sketch4'?'4':'off');save();render();cloudUpdateBatch();updateCloudPromptMode();cloudFavOverlay.classList.remove('open')}
function cloudAddResult(j,c){c.innerHTML='';if((j.images||[]).length){previewEmpty.classList.add('hidden');document.querySelector('.preview-stage').classList.add('has-results')}setResultTab(j.generation_backend==='local'?'local':'cloud');(j.images||[]).forEach((im,i)=>{const x=document.createElement('div');x.className='cloud-job';x.innerHTML=`${im.stage_label?`<b>${im.stage_label}</b>`:''}<div class="cloud-note">${j.generation_backend==='local'?'本地':'云端'} · 种子 ${j.seed??'未知'}</div><img loading="lazy" src="${im.preview_url||im.url}"><button class="cloud-dl cloud-fav">♥ 收藏</button><a class="cloud-dl" target="_blank" href="${im.url}">下载原图</a>`;x.querySelector('.cloud-fav').onclick=async e=>{e.target.disabled=true;try{await cloudApi('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:j.id,image_index:i})});e.target.textContent='✓ 已收藏'}catch(err){e.target.disabled=false;e.target.textContent='收藏失败'};};c.appendChild(x)})}
async function cloudGenerateNow(backend){if(cloudRunning[backend])return;cloudRunning[backend]=true;const b=backend==='local'?cloudGenerateLocal:cloudGenerateCloud,s=backend==='local'?cloudStatusLocal:cloudStatusCloud,r=backend==='local'?cloudResultLocal:cloudResultCloud;b.disabled=true;setLiquidLoading(b,true);s.textContent='正在提交…';r.innerHTML='';try{if(cloudSeedMode.value==='random')cloudSeed.value=cloudNewSeed();const positive=cloudPromptMode.value==='manual'?manualPositive.value.trim():cloudStripStyleTokens(buildPositive()),negative=cloudPromptMode.value==='manual'?manualNegative.value.trim():NEGATIVE;if(!positive)throw new Error('正向提示词不能为空');const body={workflow:'anima02',prompt:positive,negative_prompt:negative,prompt_mode:cloudPromptMode.value,width:+cloudW.value,height:+cloudH.value,batch:+cloudBatch.value,hd:+cloudHd.value,seed:+cloudSeed.value,seed_mode:cloudSeedMode.value,style_id:CLOUD_STYLE_ID,mode:currentMode,sequence_mode:cloudSequenceMode(),generation_backend:backend,selection_snapshot:cloudSnapshot(backend)};const q=await cloudApi('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});while(1){await new Promise(x=>setTimeout(x,3000));const j=await cloudApi('/api/job/'+q.job_id);s.textContent=(j.provider_status||j.status)+' '+(j.progress_pct||0)+'%';if(j.status==='done'){s.textContent='✓ 完成（'+j.elapsed+'秒）';cloudAddResult(j,r);break}if(j.status==='error')throw new Error(j.error||'生成失败')}}catch(e){s.textContent='✗ '+e.message}finally{cloudRunning[backend]=false;setLiquidLoading(b,false);b.disabled=false}}
async function cloudHistory(){cloudHistList.innerHTML='加载中…';try{const a=await cloudApi('/api/jobs');cloudHistList.innerHTML='';a.filter(j=>j.style_id===CLOUD_STYLE_ID).forEach(j=>{const d=document.createElement('div');d.className='cloud-job';d.innerHTML=`<b>${j.generation_backend==='local'?'本地':'云端'} · ${j.status}</b><div class="cloud-note">种子 ${j.seed??'未知'} · ${j.elapsed||''}秒</div><button class="cloud-dl">查看</button>`;d.querySelector('button').onclick=()=>cloudAddResult(j,d);cloudHistList.appendChild(d)})}catch(e){cloudHistList.textContent='历史加载失败'}}async function cloudFavorites(){cloudFavList.innerHTML='加载中…';try{const a=await cloudApi('/api/favorites');cloudFavList.innerHTML='';a.filter(f=>f.selection_snapshot?.source_page===CLOUD_PAGE_ID).forEach(f=>{const d=document.createElement('div');d.className='cloud-job';d.innerHTML=`<img loading="lazy" src="${f.preview_url||f.image_url}"><button class="cloud-dl cloud-apply">套用提示词、选项和种子</button><a class="cloud-dl" target="_blank" href="${f.image_url}">下载</a>`;d.querySelector('.cloud-apply').onclick=()=>cloudApplySnapshot(f.selection_snapshot);cloudFavList.appendChild(d)})}catch(e){cloudFavList.textContent='收藏加载失败'}}
cloudGenerateCloud.onclick=()=>cloudGenerateNow('cloud');cloudGenerateLocal.onclick=()=>cloudGenerateNow('local');importGeneratedPrompt.onclick=importGeneratedPromptToManual;cloudPromptMode.onchange=updateCloudPromptMode;cloudSeedMode.onchange=()=>{if(cloudSeedMode.value==='random')cloudSeed.value=cloudNewSeed()};if(CLOUD_HAS_SEQUENCE)cloudSequence.onchange=cloudUpdateBatch;document.querySelectorAll('[data-result-tab]').forEach(x=>x.onclick=()=>setResultTab(x.dataset.resultTab));cloudHistOpen.onclick=()=>{cloudHistOverlay.querySelector('.library-scroll').scrollTop=0;cloudHistOverlay.classList.add('open');cloudHistory()};cloudFavOpen.onclick=()=>{cloudFavOverlay.querySelector('.library-scroll').scrollTop=0;cloudFavOverlay.classList.add('open');cloudFavorites()};document.querySelectorAll('.library-overlay .cloud-close').forEach(b=>b.onclick=()=>b.closest('.library-overlay').classList.remove('open'));cloudSeed.value=cloudNewSeed();cloudUpdateBatch();updateCloudPromptMode();setResultTab('cloud');
</script>'''

def build(source_name,out_name,style,trigger,page_id,has_sequence,active):
 src=(ATT/source_name).read_text(encoding='utf8');seq='<label>铅绘分步<select id="cloudSequence"><option value="off">关闭</option><option value="3">3步</option><option value="4">4步</option></select></label>' if has_sequence else '<select id="cloudSequence" style="display:none"><option value="off">关闭</option></select>'
 top=TOPBAR.replace('__SKETCH_ACTIVE__','active' if active=='sketch' else '').replace('__GRAPHIC_ACTIVE__','active' if active=='graphic' else '')
 src=src.replace('</style>',SHARED_CSS+'\n</style>',1).replace('<body>','<body><div class="app-shell">'+top+'<main class="studio-grid"><aside class="creation-pane"><div class="creation-scroll"><div class="pane-heading original-heading"><h1>'+('原始铅绘' if active=='sketch' else '原始古风')+'</h1></div>',1).replace('<main class="wrap">','<div class="wrap original-content">',1)
 src=src.replace('</main>',UI_BASE.replace('__SEQUENCE__',seq)+'</div>'+FOOTER+PREVIEW+OVERLAYS,1)
 script=JS.replace('__STYLE__',style).replace('__TRIGGER__',trigger).replace('__PAGE__',page_id).replace('__HAS_SEQUENCE__','true' if has_sequence else 'false')
 src=src.replace('</body>',script+'</div></body>',1);(STATIC/out_name).write_text(src,encoding='utf8');print(out_name,len(src))

build('sketch_anime_dual_mode_generator (1).html','original_sketch.html','sketch','jt_style1_v1','original_sketch',True,'sketch')
build('graphic_anime_style2_dual_mode_generator (1).html','original_graphic.html','graphic','jt_style2_v1','original_graphic',False,'graphic')
